PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS products(sku TEXT PRIMARY KEY,model_id TEXT NOT NULL,name TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'SHOES',season_profile TEXT NOT NULL CHECK(season_profile IN('YEAR_ROUND','SUMMER','WINTER')),similar_group TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS batches(batch_id TEXT PRIMARY KEY,sku TEXT NOT NULL REFERENCES products(sku),manufactured_on TEXT NOT NULL,synthetic INTEGER NOT NULL DEFAULT 1 CHECK(synthetic=1));
CREATE TABLE IF NOT EXISTS orders(order_id TEXT PRIMARY KEY,ordered_at TEXT NOT NULL,fulfillment_status TEXT NOT NULL,customer_zone TEXT NOT NULL,synthetic INTEGER NOT NULL DEFAULT 1 CHECK(synthetic=1));
CREATE TABLE IF NOT EXISTS order_items(order_item_id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(order_id),sku TEXT NOT NULL REFERENCES products(sku),batch_id TEXT REFERENCES batches(batch_id),size TEXT NOT NULL,color TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),is_returnable INTEGER NOT NULL CHECK(is_returnable IN(0,1)),delivered INTEGER NOT NULL CHECK(delivered IN(0,1)),UNIQUE(order_id,sku,size,color));
CREATE TABLE IF NOT EXISTS destinations(destination_id TEXT PRIMARY KEY,name TEXT NOT NULL,destination_type TEXT NOT NULL CHECK(destination_type IN('RETAIL_STORE','OUTLET','COMPANY_WAREHOUSE')),zone TEXT NOT NULL,address TEXT NOT NULL,active INTEGER NOT NULL,dropoff_eligible INTEGER NOT NULL,capacity_units INTEGER NOT NULL,current_load_units INTEGER NOT NULL,target_sku_units INTEGER NOT NULL,transport_cost_index REAL NOT NULL,demand_index REAL NOT NULL,operational_status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS destination_distances(customer_zone TEXT NOT NULL,destination_id TEXT NOT NULL REFERENCES destinations(destination_id),distance_km REAL NOT NULL,PRIMARY KEY(customer_zone,destination_id));
CREATE TABLE IF NOT EXISTS inventory(sku TEXT NOT NULL REFERENCES products(sku),size TEXT NOT NULL,color TEXT NOT NULL,destination_id TEXT NOT NULL REFERENCES destinations(destination_id),on_hand INTEGER NOT NULL CHECK(on_hand>=0),reserved INTEGER NOT NULL CHECK(reserved>=0 AND reserved<=on_hand),PRIMARY KEY(sku,size,color,destination_id));
CREATE TABLE IF NOT EXISTS sales_volume(sales_id TEXT PRIMARY KEY,period_start TEXT NOT NULL,period_end TEXT NOT NULL,sku TEXT NOT NULL REFERENCES products(sku),size TEXT,color TEXT,batch_id TEXT REFERENCES batches(batch_id),units_sold INTEGER NOT NULL CHECK(units_sold>=0));
CREATE TABLE IF NOT EXISTS historical_complaints(complaint_id TEXT PRIMARY KEY,occurred_at TEXT NOT NULL,sku TEXT NOT NULL REFERENCES products(sku),size TEXT,color TEXT,batch_id TEXT REFERENCES batches(batch_id),category TEXT NOT NULL,detail_code TEXT,source TEXT NOT NULL CHECK(source='SYNTHETIC'));
CREATE TABLE IF NOT EXISTS return_requests(return_id TEXT PRIMARY KEY,order_item_id TEXT NOT NULL REFERENCES order_items(order_item_id),state TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 0,raw_reason TEXT,classification_json TEXT,recommendation_json TEXT,current_decision TEXT,condition_state TEXT,preliminary_grade TEXT,final_grade TEXT,simulated_calibrated_confidence REAL CHECK(simulated_calibrated_confidence BETWEEN 0 AND 1),evidence_sufficient INTEGER,seasonality_flag INTEGER CHECK(seasonality_flag IN(0,1)),destination_type TEXT,selected_destination_id TEXT REFERENCES destinations(destination_id),routing_reason TEXT,routing_score_json TEXT,fulfillment_mode TEXT,dropoff_location_id TEXT REFERENCES destinations(destination_id),return_store_name TEXT,return_store_address TEXT,return_fee REAL NOT NULL DEFAULT 0 CHECK(return_fee>=0),service_resolution_json TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK(final_grade IS NULL OR (final_grade IN('A','B','C') AND condition_state='ELIGIBLE_UNWORN')),CHECK(condition_state NOT IN('WORN_INELIGIBLE','SUSPECTED_DEFECT') OR (preliminary_grade IS NULL AND final_grade IS NULL)));
CREATE TABLE IF NOT EXISTS complaint_events(event_id TEXT PRIMARY KEY,return_id TEXT UNIQUE NOT NULL REFERENCES return_requests(return_id),occurred_at TEXT NOT NULL,sku TEXT NOT NULL,model_id TEXT NOT NULL,size TEXT,color TEXT,batch_id TEXT);
CREATE TABLE IF NOT EXISTS complaint_event_labels(event_id TEXT NOT NULL REFERENCES complaint_events(event_id),category TEXT NOT NULL,detail_code TEXT,PRIMARY KEY(event_id,category,detail_code));
CREATE TABLE IF NOT EXISTS decision_events(decision_id TEXT PRIMARY KEY,return_id TEXT NOT NULL REFERENCES return_requests(return_id),decision TEXT NOT NULL,selected_option_json TEXT,created_at TEXT NOT NULL,operation_id TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS photo_submissions(photo_id TEXT PRIMARY KEY,return_id TEXT NOT NULL REFERENCES return_requests(return_id),angle TEXT NOT NULL,local_path TEXT NOT NULL,media_type TEXT NOT NULL,bytes INTEGER NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,sha256 TEXT NOT NULL,fixture_key TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS visual_assessments(assessment_id TEXT PRIMARY KEY,return_id TEXT NOT NULL REFERENCES return_requests(return_id),evidence_sufficient INTEGER NOT NULL,eligibility_state TEXT,preliminary_grade TEXT,simulated_calibrated_confidence REAL,evidence_json TEXT NOT NULL,uncertainty_json TEXT NOT NULL,retakes_json TEXT NOT NULL,fixture_key TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS review_queue(review_id TEXT PRIMARY KEY,return_id TEXT NOT NULL REFERENCES return_requests(return_id),assessment_id TEXT NOT NULL REFERENCES visual_assessments(assessment_id),status TEXT NOT NULL CHECK(status IN('OPEN','RESOLVED')),preliminary_grade TEXT,resolution TEXT,final_grade TEXT,reviewer_note TEXT,created_at TEXT NOT NULL,resolved_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_review ON review_queue(return_id) WHERE status='OPEN';
CREATE TABLE IF NOT EXISTS early_warning_alerts(alert_id TEXT PRIMARY KEY,fingerprint TEXT NOT NULL,window_start TEXT NOT NULL,window_end TEXT NOT NULL,dimension_type TEXT NOT NULL,dimension_value TEXT NOT NULL,category TEXT NOT NULL,detail_code TEXT,complaint_count INTEGER NOT NULL,units_sold INTEGER NOT NULL,complaint_rate REAL NOT NULL,baseline_rate REAL NOT NULL,lift REAL NOT NULL,threshold_json TEXT NOT NULL,evidence_json TEXT NOT NULL,recommendation TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',created_at TEXT NOT NULL,UNIQUE(fingerprint,window_end));
CREATE TABLE IF NOT EXISTS routes(route_id TEXT PRIMARY KEY,return_id TEXT UNIQUE NOT NULL REFERENCES return_requests(return_id),condition_key TEXT NOT NULL,final_grade TEXT,seasonality_flag INTEGER NOT NULL,destination_type TEXT NOT NULL,destination_id TEXT REFERENCES destinations(destination_id),fulfillment_mode TEXT,total_score REAL,score_json TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fulfillment_artifacts(artifact_id TEXT PRIMARY KEY,return_id TEXT NOT NULL REFERENCES return_requests(return_id),artifact_type TEXT NOT NULL,local_path TEXT NOT NULL,sha256 TEXT NOT NULL,demo_marking TEXT NOT NULL CHECK(demo_marking='DEMO / NOT VALID FOR SHIPPING'),instructions TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activity_log(activity_id INTEGER PRIMARY KEY AUTOINCREMENT,return_id TEXT REFERENCES return_requests(return_id),agent_name TEXT NOT NULL,action TEXT NOT NULL,rationale TEXT NOT NULL,input_json TEXT NOT NULL,output_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS activity_no_update BEFORE UPDATE ON activity_log BEGIN SELECT RAISE(ABORT,'activity log is append-only'); END;
CREATE TRIGGER IF NOT EXISTS activity_no_delete BEFORE DELETE ON activity_log BEGIN SELECT RAISE(ABORT,'activity log is append-only'); END;
CREATE TABLE IF NOT EXISTS processed_operations(operation_id TEXT PRIMARY KEY,return_id TEXT NOT NULL REFERENCES return_requests(return_id),command_name TEXT NOT NULL,result_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_returns_state ON return_requests(state); CREATE INDEX IF NOT EXISTS idx_inventory_sku ON inventory(sku,size,color); CREATE INDEX IF NOT EXISTS idx_complaints ON historical_complaints(sku,size,category,detail_code); CREATE INDEX IF NOT EXISTS idx_activity_return ON activity_log(return_id,activity_id);
-- v2 additive tables (new nullable columns on existing tables live in db/migrations.py)
CREATE TABLE IF NOT EXISTS customer_messages(message_id TEXT PRIMARY KEY,return_id TEXT NOT NULL REFERENCES return_requests(return_id),message_type TEXT NOT NULL,channel TEXT NOT NULL CHECK(channel='EMAIL'),recipient TEXT NOT NULL CHECK(recipient LIKE 'customer-%@example.test'),subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL CHECK(status='MOCK_SENT'),sent_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS staff_destination_decisions(decision_id TEXT PRIMARY KEY,return_id TEXT NOT NULL REFERENCES return_requests(return_id),suggested_destination_id TEXT REFERENCES destinations(destination_id),suggested_destination_type TEXT,chosen_destination_id TEXT NOT NULL REFERENCES destinations(destination_id),chosen_destination_type TEXT NOT NULL CHECK(chosen_destination_type IN('RETAIL_STORE','OUTLET','COMPANY_WAREHOUSE')),deviates_from_suggestion INTEGER NOT NULL CHECK(deviates_from_suggestion IN(0,1)),reason TEXT,decided_by TEXT NOT NULL,decided_at TEXT NOT NULL,CHECK(deviates_from_suggestion=0 OR length(trim(COALESCE(reason,'')))>0));
CREATE TABLE IF NOT EXISTS alert_status_events(event_id TEXT PRIMARY KEY,alert_id TEXT NOT NULL REFERENCES early_warning_alerts(alert_id),from_status TEXT NOT NULL,to_status TEXT NOT NULL CHECK(to_status IN('OPEN','INVESTIGATING','CLOSED')),changed_by TEXT NOT NULL,note TEXT,changed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS demo_settings(setting_key TEXT PRIMARY KEY,setting_value TEXT NOT NULL,updated_by TEXT,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_customer_messages_return ON customer_messages(return_id,sent_at); CREATE INDEX IF NOT EXISTS idx_staff_destination_return ON staff_destination_decisions(return_id,decided_at); CREATE INDEX IF NOT EXISTS idx_alert_status_events ON alert_status_events(alert_id,changed_at);
